	private static double maximumMetric(String plan, String metricName) {
		Matcher matcher = Pattern
				.compile(Pattern.quote(metricName) + "=([-+]?\\d+(?:\\.\\d+)?(?:[Ee][-+]?\\d+)?[KMB]?)")
				.matcher(plan);
		double maximum = Double.NaN;
		while (matcher.find()) {
			maximum = Math.max(Double.isNaN(maximum) ? 0.0d : maximum, parsePlanRows(matcher.group(1)));
		}
		return maximum;
	}

	private static double statementProviderProbes(String plan) {
		return metricOrZero(plan, "plannedFrontierPrimitiveSnapshotProbes")
				+ metricOrZero(plan, "plannedFrontierQueryIndexForwardMappedProbes")
				+ metricOrZero(plan, "plannedFrontierQueryIndexReverseMappedProbes");
	}

	private static double metricOrZero(String plan, String metricName) {
		double value = maximumMetric(plan, metricName);
		return Double.isNaN(value) ? 0.0d : value;
	}

	private static void assertMappedV2Statistics(PlanSnapshot snapshot, String label) {
		String plan = snapshot.plan();
		assertTrue(plan.contains("plannedFrontierStatus=ready")
				&& plan.contains("plannedFrontierDisposition=mapped_statistics")
				&& plan.contains("plannedEstimateSource=frontier-v2-"),
				() -> "The " + label + " q9 plan must use a READY queryable V2 generation:\n" + plan);
		assertFalse(plan.contains("replayable_source") || plan.contains("payload_writer")
				|| plan.contains("plannedFrontierQueryIndexStatus="),
				() -> "The " + label + " q9 plan must not enter a V1 derivative/materialization path:\n" + plan);
	}

	private static double parsePlanRows(String value) {
		double multiplier = 1.0d;
		if (value.endsWith("K")) {
			multiplier = 1_000.0d;
			value = value.substring(0, value.length() - 1);
		} else if (value.endsWith("M")) {
			multiplier = 1_000_000.0d;
			value = value.substring(0, value.length() - 1);
		} else if (value.endsWith("B")) {
			multiplier = 1_000_000_000.0d;
			value = value.substring(0, value.length() - 1);
		}
		return Double.parseDouble(value) * multiplier;
	}

	private static void restoreProperty(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previousValue);
		}
	}

	private static final class RunQueryPlanState extends ThemeQueryPlanRunBenchmark.BaseState {

		private PlanSnapshot planSnapshot() {
			return planSnapshot(query);
		}

		private PlanSnapshot uncachedPlanSnapshot(long invocation) {
			return planSnapshot(ThemeQueryPlanRunBenchmark.alphaRenameVariables(query, invocation));
		}

		private PlanSnapshot planSnapshot(String queryText) {
			var tupleQuery = connection.prepareTupleQuery(queryText);
			tupleQuery.setIncludeInferred(false);
			tupleQuery.setMaxExecutionTime(60);
			Explanation explanation = LmdbBenchmarkQueryPlan.withCascadesOptimizationTimeout(60,
					() -> tupleQuery.explain(Explanation.Level.Optimized));
			return new PlanSnapshot(explanation.toString(),
					new TupleExprIRRenderer().render((TupleExpr) explanation.tupleExpr()));
		}

		private void assertSelectiveNativeAccess(Duration planningLimit, boolean broadControl, Path evidence)
				throws Exception {
			LmdbFiniteCycleAccessProof.verify(store, query,
					ThemeQueryCatalog.expectedCountBindingValueFor(Theme.SOCIAL_MEDIA, z_queryIndex).orElseThrow(),
					planningLimit, broadControl, evidence);
		}

		private void assertExpectedQueryResult() {
			try (LmdbBenchmarkQueryPlan plan = preparePlan(false)) {
				assertExpectedResult(evaluate(plan));
			}
		}

		private void disableTelemetryTeardown() {
			query = null;
		}
	}

	private record PlanSnapshot(String plan, String renderedQuery) {
	}
